import java.util.Arrays; public class Problem9_PairSumSortedArray { static int[]pairSumSorted(int[]a,int target){int l=0,r=a.length-1;while(l<r){long s=(long)a[l]+a[r];if(s==target)return new int[]{a[l],a[r]};if(s<target)l++;else r--;}return null;} public static void main(String[]x){int[]p=pairSumSorted(new int[]{-4,-1,0,3,5,9},4);System.out.println(p==null?"Not Found":Arrays.toString(p));}}